#!/usr/bin/env python3
import types,sys,json,os,csv
from pathlib import Path
pb=types.ModuleType("pseudobulk_contract")
exec(compile(bytes.fromhex(""),"bundled-pseudobulk-contract","exec"),pb.__dict__)
guard=types.ModuleType("network_guard")
exec(compile(bytes.fromhex(""),"bundled-study-guard","exec"),guard.__dict__)
bc=types.ModuleType("research_b_counts");bc.pb=pb
gs=types.ModuleType("cachexia_plan_guards");gs.complete_family=guard.complete_family
previous={k:sys.modules.get(k) for k in ["research_b_counts","cachexia_plan_guards"]}
sys.modules["research_b_counts"]=bc;sys.modules["cachexia_plan_guards"]=gs
component=types.ModuleType("c_network_method");component._EMBEDDED_SOURCE_IDS={'component_sha256': 'b36e59f4e127f735152dfcfd83b442390253db5ba3d34342899b4fe87482ea0c', 'guard_sha256': 'f12dfbfc7ca168903f16efa1410399ea982521534a243dbc96dc365de79113ca', 'support_sha256': '9728e902e032dd948f8906a5682a42a28d4d2abfc39db96b2265c5670572dca6'}
try:
    exec(compile(bytes.fromhex(""),"bundled-c-network-method","exec"),component.__dict__)
finally:
    for key,value in previous.items():
        if value is None:sys.modules.pop(key,None)
        else:sys.modules[key]=value

def run():
    inputs = [Path(os.environ['AUTONOMICS_INPUT'+str(i)]) for i in range(6)]
    outputs = [Path(os.environ['AUTONOMICS_OUTPUT'+str(i)]) for i in range(5)]
    pb.require([p.name for p in outputs] == component.OUTPUTS and len({p.parent.absolute() for p in outputs}) == 1,
               'complete declared network ports in one private directory required')
    parent = outputs[0].parent.absolute()
    pb.require(all(p.is_absolute() and '..' not in p.parts for p in outputs) and parent != Path('/'),
               'private absolute output paths without traversal required')
    pb.require(not any(os.path.lexists(p) for p in outputs), 'output exists; refusing overwrite')
    pb.require(not any(p.is_symlink() for p in [parent, *parent.parents]), 'symlink output ancestor')
    parent.mkdir(parents=True, exist_ok=True)
    bundle = parent / '.c-network-complete'
    pb.require(not os.path.lexists(bundle), 'complete network bundle already exists')
    audit = component.execute(inputs[0], dict(zip(component.INPUTS, inputs[1:])), bundle)
    # A complete private bundle exists before linking. If any port fails,
    # execution fails and the container engine must publish no normal artifacts.
    for target in outputs: os.link(bundle/target.name, target)
    print(json.dumps({'scope': audit['scope'], 'formal_authorized': False, 'scientific_G0_granted': False}))
if __name__ == '__main__':
    try: run()
    except (ValueError, KeyError, TypeError, OSError, UnicodeError, csv.Error, OverflowError) as e:
        print('BLOCKED: '+str(e), file=sys.stderr); raise SystemExit(2)
